   [144]={next_id=145, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="玩家名字，阿尔戈姑娘，请到我的身后来。", msg_color="", msg_size=0, talker="鸣晔", audio="", img="arts/ui/bg/story/storybg_ACT304_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530_2", 0, 0, 71.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [145]={next_id=146, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你们重新聚在了一处，那股诡异的压迫力仿佛有所减弱，鸣晔身上的力量仿佛在与它对抗。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4530_2", 0, 0, 71.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
